def gen(rng):
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{a} {b}' for a, b in ps)
    tests = [fmt([(0, 0)]), fmt([(5, 5)]), fmt([(1, 2)]), fmt([(-7, 7)]),
             fmt([(10**9, -10**9)]), fmt([(-10**9, -10**9), (10**9, 10**9), (0, -10**9)]),
             fmt([(0, 1), (1, 0), (-1, 0), (0, -1)])]
    for n in (2, 3, 5, 8, 12):
        for _ in range(3):
            hi = rng.choice([5, 100, 10**9])
            tests.append(fmt([(rng.randint(-hi, hi), rng.randint(-hi, hi)) for _ in range(n)]))
    tests.append(fmt([(rng.randint(-10**9, 10**9), rng.randint(-10**9, 10**9)) for _ in range(100000)]))
    tests.append(fmt([(rng.randint(-1000, 1000), rng.randint(-1000, 1000)) for _ in range(100000)]))
    return tests

